package com.wiseway.service;
import com.wiseway.domain.TransportMode; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import static org.junit.jupiter.api.Assertions.*;
class FareCalculationServiceTest { @Test void roadFareChangesWithDistanceAndMode(){var s=new FareCalculationService();var near=s.calculate(TransportMode.AUTO,1000);var far=s.calculate(TransportMode.AUTO,10000);assertTrue(far.amount().compareTo(near.amount())>0);assertNotEquals(far.amount(),s.calculate(TransportMode.CAB,10000).amount());} @Test void officialTransitFareIsUnavailableWithoutTable(){assertNull(new FareCalculationService().calculate(TransportMode.METRO,5000).amount());} }
